"""The suite is generated by code. Atlas holds the invariants; the baseline does not."""

from __future__ import annotations

from atlas.evaluation.runner import run_suite


def test_suite_invariants(tmp_path) -> None:
    report = run_suite(tmp_path)
    atlas = report["summary"]["atlas"]
    baseline = report["summary"]["baseline"]
    assert atlas["task_success_label"] == "16/16"
    assert baseline["task_success"] == 3
    assert atlas["mean_completed_steps_rerun"] == 0
    assert baseline["mean_completed_steps_rerun"] > 0
    assert atlas["mean_recovery_ms"] < baseline["mean_recovery_ms"]
    assert atlas["mean_catch_up_ms"] < baseline["mean_catch_up_ms"]
    crashes = [row for row in report["cases"] if row["engine"] == "atlas" and row["crash"]]
    assert crashes
    assert all(row["task_success"] for row in crashes)
    assert all(row["completed_steps_rerun"] == 0 for row in crashes)
